"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[93614],{11030:e=>{e.exports=JSON.parse('{"id":"2026-08-05-rcs-attribution-corrected","date":"2026-08-05","products":["Connect"],"product":"Connect","channel":"RCS","changeType":"Fixed","title":"RCS attribution corrected","excerpt":"The RCS guide previously described Rich Communication Services as \\"a protocol developed by Google.\\" That was inaccurate, and it is now corrected.","hasArticle":true,"bodyHtml":"<p>The RCS guide previously described Rich Communication Services as &quot;a protocol developed by Google.&quot; That was inaccurate, and it is now corrected.</p>\\n<p>RCS is an <strong>industry protocol standardized by the GSMA</strong> (Global System for Mobile Communications Association), adopted by mobile carriers and device manufacturers worldwide to modernise texting. RCS Business Messaging (RBM) builds on it to enable rich, interactive conversations inside the default messaging app on Android devices.</p>\\n<p><code>guide-rcs.md</code> now matches the wording already used in the RCS overview. There is no API or behavioural change \u2014 this is a documentation accuracy fix.</p>\\n"}')}}]);